# Code generated by Claude
"""
Tests of the pouring scene (src/pour_scene.py, B3).

    MUJOCO_GL=egl python experiments/pour_scene_test.py

1. The scene: two identical 100 g hollow beakers, the balls (their count, mass, radius; the mouth is at least 5 balls across), the placement (balls inside the full beaker, nothing outside),
   the contact settings (a ball-on-glass contact uses the ball's 0.3 friction, not the glass's 1.0), and the scene without `pour` is unchanged.
2. The draw: the same seed gives the same setup, different seeds give both beakers and counts inside the range.
3. At rest: after the scene settles every ball is still in the beaker, none below the bench, and they are nearly still.
4. A gentle kinematic pour (experiments/pour_helpers.py, 15 degrees per second) from each beaker into the other (so both tilt directions): the balls flow without jamming (all of them
   arrive, at least the 90 % of design plan §6, and none are spilled; a faster tilt of 30 degrees per second let the first bead overshoot the 7 cm opening), the physics stays finite.
"""

import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from pour_helpers import run_pour, settle  # noqa: E402
from src.pour_scene import BALL_PREFIX, ball_counts, draw_setup  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BEAKER_CFG, POUR_CFG  # noqa: E402

results = []
NO_LIQUID = {**BEAKER_CFG, "liquid_mass": 0.0}


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    print("\n1. the scene")
    cfg = {**POUR_CFG, "n_balls": 40, "full": "first"}
    sim = load_task(cameras=False, pour=cfg)
    m, d = sim.model, sim.data
    balls = [b for b in range(m.nbody) if m.body(b).name.startswith(BALL_PREFIX)]
    check("40 balls of 2.5 g, radius 5.5 mm", len(balls) == 40 and abs(m.body_mass[balls[0]] - 0.0025) < 1e-9 and abs(m.geom_size[m.geom(f"{BALL_PREFIX}0_geom").id][0] - 0.0055) < 1e-9)
    mouth = 2 * (BEAKER_CFG["outer_diameter"] / 2 - BEAKER_CFG["wall"])
    check("the beaker's mouth is at least 5 balls across (no arching)", mouth / (2 * cfg["ball_radius"]) >= 5.0, f"{mouth / (2 * cfg['ball_radius']):.2f} balls")
    check("both beakers are the 100 g glass beaker with no rigid liquid mass", all(abs(m.body_mass[m.body(b).id] - 0.1) < 1e-6 for b in ("task_beaker", "task_beaker_2")))
    check("the second beaker has its own gripper contact pairs (300 = 2 beakers x 150)", m.npair == 300, f"{m.npair}")
    b1, b2 = d.xpos[m.body("task_beaker").id], d.xpos[m.body("task_beaker_2").id]
    check("the beakers stand 20 cm apart on the bench, the first at its task position", abs(np.linalg.norm(b2[:2] - b1[:2]) - 0.20) < 1e-9 and np.allclose(b1[:2], [1.0, 0.66]), f"{np.round(b1, 3)} {np.round(b2, 3)}")
    P = np.array([d.xpos[b] for b in balls]) - b1
    check("every ball starts inside the first beaker (within its inside radius and below its rim)", (np.hypot(P[:, 0], P[:, 1]) < 0.0336 - 0.005).all() and (P[:, 2] > 0.002).all() and (P[:, 2] < BEAKER_CFG["height"]).all(), f"radius max {1000 * np.hypot(P[:, 0], P[:, 1]).max():.1f} mm, height max {1000 * P[:, 2].max():.0f} mm")
    plain = load_task(cameras=False)
    check("without `pour` the scene is as before: no second beaker, no balls, one beaker's 150 pairs", plain.model.npair == 150 and not any(plain.model.body(b).name.startswith(BALL_PREFIX) for b in range(plain.model.nbody)))
    del plain

    print("\n2. the draw")
    a, b = draw_setup(POUR_CFG, 5), draw_setup(POUR_CFG, 5)
    draws = [draw_setup(POUR_CFG, s) for s in range(40)]
    check("the same seed gives the same setup", a == b)
    check("40 seeds give both beakers as the full one and counts inside 30 to 60", {x["full"] for x in draws} == {"first", "second"} and all(30 <= x["n_balls"] <= 60 for x in draws) and len({x["n_balls"] for x in draws}) > 10)

    print("\n3. at rest")
    hold = settle(sim, 1.0)
    P = np.array([d.xpos[b] for b in balls]) - d.xpos[m.body("task_beaker").id]
    counts = ball_counts(m, d, cfg, NO_LIQUID, "task_beaker", "task_beaker_2")
    check("after settling all 40 balls are still in the first beaker", counts["in_source"] == 40 and counts["spilled"] == 0, str(counts))
    v = np.array([np.linalg.norm(d.cvel[b][3:]) for b in balls])
    check("the balls are nearly still (largest speed under 2 cm/s)", v.max() < 0.02, f"{100 * v.max():.2f} cm/s")
    check("the pile is low: the top ball is under 4 cm above the bottom", P[:, 2].max() < 0.045, f"{1000 * P[:, 2].max():.0f} mm")
    ball_g, wall_g = m.geom(f"{BALL_PREFIX}0_geom").id, [m.geom(f"task_beaker_wall_{i}").id for i in range(24)]
    mu = [d.contact[i].friction[0] for i in range(d.ncon) if (d.contact[i].geom1 == ball_g and d.contact[i].geom2 in wall_g) or (d.contact[i].geom2 == ball_g and d.contact[i].geom1 in wall_g)]
    allmu = [d.contact[i].friction[0] for i in range(d.ncon) if m.geom(d.contact[i].geom1).name.startswith(BALL_PREFIX) != m.geom(d.contact[i].geom2).name.startswith(BALL_PREFIX)]
    check("a ball-on-glass contact uses the ball's friction 0.3 (not the glass's 1.0)", len(allmu) > 0 and abs(np.mean(allmu) - 0.3) < 1e-6, f"{len(allmu)} ball-vs-other contacts, mean friction {np.mean(allmu):.3f}")
    del sim

    print("\n4. kinematic pours")
    for full, src, dst in (("first", "task_beaker", "task_beaker_2"), ("second", "task_beaker_2", "task_beaker")):
        for n in (40, 60):
            cfg = {**POUR_CFG, "n_balls": n, "full": full}
            sim = load_task(cameras=False, pour=cfg)
            hold = settle(sim, 1.0)
            r = run_pour(sim, hold, src, dst)
            counts = ball_counts(sim.model, sim.data, cfg, NO_LIQUID, src, dst)
            ok = np.isfinite(sim.data.qpos).all() and np.isfinite(sim.data.qvel).all()
            check(f"{n} balls from the {full} beaker: the physics stays finite", ok)
            check(f"{n} balls from the {full} beaker: at least 90 % arrive in the other beaker and none are spilled", counts["transferred"] >= 0.9 * n and counts["spilled"] == 0,
                  f"{counts} ({100 * counts['transferred'] / n:.0f} % transferred; {r['mean_ms']:.2f} ms per step, at most {r['max_ms']:.2f} in a 0.25 s window, up to {r['max_contacts']} contacts)")
            del sim
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
